import{_ as e,c as r,o as h,ah as i}from"./chunks/framework.Dnh4IO1K.js";const p=JSON.parse('{"title":"大壯","description":"焦氏易林注 - 大壯","frontmatter":{"title":"大壯","description":"焦氏易林注 - 大壯"},"headers":[],"relativePath":"classics/jiaoyilin/034.md","filePath":"classics/jiaoyilin/034.md"}'),l={name:"classics/jiaoyilin/034.md"};function n(d,a,t,o,s,c){return h(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="大壯" tabindex="-1">大壯 <a class="header-anchor" href="#大壯" aria-label="Permalink to “大壯”">​</a></h1><h3 id="大壯-1" tabindex="-1">大壯 <a class="header-anchor" href="#大壯-1" aria-label="Permalink to “大壯”">​</a></h3><h3 id="大壯之乾" tabindex="-1">大壯之乾 <a class="header-anchor" href="#大壯之乾" aria-label="Permalink to “大壯之乾”">​</a></h3><h3 id="林辭" tabindex="-1">林辭 <a class="header-anchor" href="#林辭" aria-label="Permalink to “林辭”">​</a></h3><p>金齒鐵牙，壽考宜家。年歲有儲，貪利者得，離其咎憂。</p><h3 id="注" tabindex="-1">注 <a class="header-anchor" href="#注" aria-label="Permalink to “注”">​</a></h3><p>《大壯》中爻兌，兌為齒牙，乾為金鐵，故曰金齒鐵牙。伏艮為壽考、為家，乾為年歲、為富，故有儲、故利得。乾為吉慶，故離咎憂。</p><h3 id="大壯之坤" tabindex="-1">大壯之坤 <a class="header-anchor" href="#大壯之坤" aria-label="Permalink to “大壯之坤”">​</a></h3><h3 id="林辭-1" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-1" aria-label="Permalink to “林辭”">​</a></h3><p>家給人足，頌聲並作。四夷賓服，乾戈閣。</p><h3 id="注-1" tabindex="-1">注 <a class="header-anchor" href="#注-1" aria-label="Permalink to “注”">​</a></h3><p>《大壯》震為人，伏艮為家，坤富，故家給人足。震言為頌、為聲，坤陰為夷順、為服，震卦數四，為賓客，故曰四夷賓服。艮為乾戈，艮伏，故曰乾戈閣，坤為也。○，宋元本作囊，依汲古。</p><h3 id="大壯之屯" tabindex="-1">大壯之屯 <a class="header-anchor" href="#大壯之屯" aria-label="Permalink to “大壯之屯”">​</a></h3><h3 id="林辭-2" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-2" aria-label="Permalink to “林辭”">​</a></h3><p>獮猴冠帶，盜載非位。眾犬嘈吠，狂走蹶足。</p><h3 id="注-2" tabindex="-1">注 <a class="header-anchor" href="#注-2" aria-label="Permalink to “注”">​</a></h3><p>震為獮猴，艮為冠，伏巽為帶。坎為盜，震車為載，艮為位，古君子方許乘車，今載以盜，故曰非位。艮為犬，坤眾震鳴，故曰眾犬嘈吠。震為足、為走，坎蹇故蹶足也。○嘈，汲古作持，依宋元本。蹶，宋元本作厥，依汲古。</p><h3 id="大壯之蒙" tabindex="-1">大壯之蒙 <a class="header-anchor" href="#大壯之蒙" aria-label="Permalink to “大壯之蒙”">​</a></h3><h3 id="林辭-3" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-3" aria-label="Permalink to “林辭”">​</a></h3><p>心患其身，不念安存。忠臣孝子，為國除患。</p><h3 id="注-3" tabindex="-1">注 <a class="header-anchor" href="#注-3" aria-label="Permalink to “注”">​</a></h3><p>坎為心、為患、為念，坤為身、為安，言身之所以安存，由心時時慮患也。坤為臣，坎為忠，故曰忠臣。震為子，坤順，故曰孝子。坤為國，坎為患，震解故除患。</p><h3 id="大壯之需" tabindex="-1">大壯之需 <a class="header-anchor" href="#大壯之需" aria-label="Permalink to “大壯之需”">​</a></h3><h3 id="林辭-4" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-4" aria-label="Permalink to “林辭”">​</a></h3><p>君不明德，臣亂為惑。丞相命馬，胡亥失所。</p><h3 id="注-4" tabindex="-1">注 <a class="header-anchor" href="#注-4" aria-label="Permalink to “注”">​</a></h3><p>乾為君、為德，坎隱故不明。乾伏坤，坤為臣、為亂、為惑，故曰臣亂為惑。兌為輔相，兌口為命，乾為馬，伏坤為胡，乾居亥，故曰胡亥。坎為失，謂趙高命鹿為馬而弒胡亥。胡亥，秦二世名。乾為君，居亥，胡亥，亦國君用字。取象神妙如此。○馬，汲古作駕，非，依宋元本。</p><h3 id="大壯之訟" tabindex="-1">大壯之訟 <a class="header-anchor" href="#大壯之訟" aria-label="Permalink to “大壯之訟”">​</a></h3><h3 id="林辭-5" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-5" aria-label="Permalink to “林辭”">​</a></h3><p>東行西窮，南北無功。張伯賣鹿，從者失羊。</p><h3 id="注-5" tabindex="-1">注 <a class="header-anchor" href="#注-5" aria-label="Permalink to “注”">​</a></h3><p>通《明夷》。震為東、為行，坎為西，坎陷故窮。離南坎北，坤喪故無功。震為伯、為鹿，震為商賈，故賣鹿。震為從、為羊，本《大壯上六》也，坤為失。○賣，汲古作賈，依宋元本。</p><h3 id="大壯之師" tabindex="-1">大壯之師 <a class="header-anchor" href="#大壯之師" aria-label="Permalink to “大壯之師”">​</a></h3><h3 id="林辭-6" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-6" aria-label="Permalink to “林辭”">​</a></h3><p>鹿下西山，欲歸其群。逢羿鋒箭，死於矢端。</p><h3 id="注-6" tabindex="-1">注 <a class="header-anchor" href="#注-6" aria-label="Permalink to “注”">​</a></h3><p>震為鹿、為陵，坎西，故曰西山。坤為群，群者，五陰也。震為歸，坤為惡，故曰羿。坎為箭、為矢、為鋒，鋒，矢末也。坤為死，在坎上，故死於矢端。○歸，汲古作保，鋒箭作箭鋒，依宋元本。死，元本作無，依宋本、汲古。</p><h3 id="大壯之比" tabindex="-1">大壯之比 <a class="header-anchor" href="#大壯之比" aria-label="Permalink to “大壯之比”">​</a></h3><h3 id="林辭-7" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-7" aria-label="Permalink to “林辭”">​</a></h3><p>明夷兆初，三日為災。以讒復歸，名曰豎牛。剝亂叔孫，餒卒虛丘。</p><h3 id="注-7" tabindex="-1">注 <a class="header-anchor" href="#注-7" aria-label="Permalink to “注”">​</a></h3><p>坎黑坤晦，故曰明夷。坤為兆，《左傳昭五年》：&quot;初，穆子生穆，莊叔筮之，遇《明夷》之《謙》&quot;，初爻動，故曰明夷兆初。坎為災，艮為日，數三，故曰三日為災。坎上下兩兌相背，故曰讒。大壯震為歸，故曰以讒復歸。艮為名、為豎、為牛，坤為亂，艮為剝、為叔孫，故曰剝亂叔孫。坤為餒、為卒、為虛，艮為丘，言魯叔孫穆子為豎牛所亂，三日不得食而飢死也。與《剝》之《比》參看。○日，汲古作旦，依宋元本。復，宋元本作後，依汲古。餒，元本作喂，依宋本、汲古。</p><h3 id="大壯之小畜" tabindex="-1">大壯之小畜 <a class="header-anchor" href="#大壯之小畜" aria-label="Permalink to “大壯之小畜”">​</a></h3><h3 id="林辭-8" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-8" aria-label="Permalink to “林辭”">​</a></h3><p>秦失嘉居，河伯為怪。還其銜璧，神怒不佑。織組無文，燒香不芬。</p><h3 id="注-8" tabindex="-1">注 <a class="header-anchor" href="#注-8" aria-label="Permalink to “注”">​</a></h3><p>通《豫》。兌西故曰秦。艮為居，震為嘉，坎失，故失嘉居。震為伯，坎為河、為怪，故曰河伯為怪。震為璧、為銜、為還、為神、為怒。按：《秦紀》使者從關東夜過華陰，有人持璧遮使者曰：為吾遺滈池君，今年祖龍死，因置其璧去，忽不見，始皇視之，乃二十八年過江所沈璧也，未幾，始皇果死，故曰還璧、曰不佑。坤為文、為帛，坎為伏，故組織無文。本卦巽為香、為芬，互離為燒，風散故不芬。</p><h3 id="大壯之履" tabindex="-1">大壯之履 <a class="header-anchor" href="#大壯之履" aria-label="Permalink to “大壯之履”">​</a></h3><h3 id="林辭-9" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-9" aria-label="Permalink to “林辭”">​</a></h3><p>至德之君，禍不過鄰。使我世存，身無患災。</p><h3 id="注-9" tabindex="-1">注 <a class="header-anchor" href="#注-9" aria-label="Permalink to “注”">​</a></h3><p>乾為德、為君，離東為鄰，離亂兌毀，故曰禍不過鄰，言不及乾也。通《謙》。坤為我、為身、為世，坎為災患，震解故無災患。○至德，宋元本作德至，依汲古。</p><h3 id="大壯之泰" tabindex="-1">大壯之泰 <a class="header-anchor" href="#大壯之泰" aria-label="Permalink to “大壯之泰”">​</a></h3><h3 id="林辭-10" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-10" aria-label="Permalink to “林辭”">​</a></h3><p>眾惡之堂，相聚為殃。幽毒良人，使道不通。</p><h3 id="注-10" tabindex="-1">注 <a class="header-anchor" href="#注-10" aria-label="Permalink to “注”">​</a></h3><p>坤為眾、為惡，伏艮為堂，故曰眾惡之堂。坤為聚、為殃、為幽毒，震為人，乾為善，故曰良人。乾在下故曰幽毒良人。乾為道，坤閉，故道不通。○幽，宋元本作出，依汲古。</p><h3 id="大壯之否" tabindex="-1">大壯之否 <a class="header-anchor" href="#大壯之否" aria-label="Permalink to “大壯之否”">​</a></h3><h3 id="林辭-11" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-11" aria-label="Permalink to “林辭”">​</a></h3><p>三痴六狂，欲之平鄉。迷惑失道，不知昏明。</p><h3 id="注-11" tabindex="-1">注 <a class="header-anchor" href="#注-11" aria-label="Permalink to “注”">​</a></h3><p>通《泰》。坤為痴，震數三，故曰三痴。震為狂，乾數六，故曰六狂。震為之，坤為平鄉、為迷惑，乾為道，迷惑故失道。坤為昏，震旦為明。</p><h3 id="大壯之同人" tabindex="-1">大壯之同人 <a class="header-anchor" href="#大壯之同人" aria-label="Permalink to “大壯之同人”">​</a></h3><h3 id="林辭-12" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-12" aria-label="Permalink to “林辭”">​</a></h3><p>老弱無子，不能自理。郭氏雖憂，終不離咎。管子治國，侯伯來服。乘輿八百，尊祀祖德。</p><h3 id="注-12" tabindex="-1">注 <a class="header-anchor" href="#注-12" aria-label="Permalink to “注”">​</a></h3><p>通《師》。乾老坤弱，震子坤喪，故無子。坤為自、為理，柔弱故不能自理。坤為郭，坎為憂咎，郭為齊滅，故曰終不離咎。震為竹、為管子，坤為國，震為侯伯，坤順為服，坤為乘輿，卦數八，故曰乘輿八百。乾為祖、為德、為尊，坎為祀也。○此林前四句與後四句吉凶不同意，亦不屬，顯為兩林，非盡焦氏。</p><h3 id="大壯之大有" tabindex="-1">大壯之大有 <a class="header-anchor" href="#大壯之大有" aria-label="Permalink to “大壯之大有”">​</a></h3><h3 id="林辭-13" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-13" aria-label="Permalink to “林辭”">​</a></h3><p>褒後生蛇，經老日微。退跌衰耄，酒滅黃離。</p><h3 id="注-13" tabindex="-1">注 <a class="header-anchor" href="#注-13" aria-label="Permalink to “注”">​</a></h3><p>通《比》。坤為後，昔周人發龍化為玄黿，後宮童女遭之而孕，生褒姒。玄黿，蜥蜴也，亦非蛇，且卦無蛇象，而各本皆作蛇，元如何也。坤帛為經，坎為跌，乾為衰老，坎為酒，離為黃，於卦句雖偶合而語皆難解，疑訛字仍多。</p><h3 id="大壯之謙" tabindex="-1">大壯之謙 <a class="header-anchor" href="#大壯之謙" aria-label="Permalink to “大壯之謙”">​</a></h3><h3 id="林辭-14" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-14" aria-label="Permalink to “林辭”">​</a></h3><p>驄黑，東歸高鄉。白虎推輪，蒼龍把衡。遂至夷傷，不離咎殃。</p><h3 id="注-14" tabindex="-1">注 <a class="header-anchor" href="#注-14" aria-label="Permalink to “注”">​</a></h3><p>解詳《遯》之《震》。○，汲古作鬣，高作南，均依宋元本。遂，元本作逐，非，依宋本、汲古。</p><h3 id="大壯之豫" tabindex="-1">大壯之豫 <a class="header-anchor" href="#大壯之豫" aria-label="Permalink to “大壯之豫”">​</a></h3><h3 id="林辭-15" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-15" aria-label="Permalink to “林辭”">​</a></h3><p>信譎龍且，塞水上流。半渡決囊，楚師覆亡。</p><h3 id="注-15" tabindex="-1">注 <a class="header-anchor" href="#注-15" aria-label="Permalink to “注”">​</a></h3><p>坎為信，正反兩震言相背，故曰譎。震為龍，故曰信譎龍且。艮為防、為塞，卦本坤體，亦為水，陽在坤上，故曰塞水上流。坤為囊，艮手為決，震為渡，陽居中，故曰半渡。震木為楚，坤為師，坤喪故覆亡。《史記》：&quot;韓信與項羽將龍且，戰於濰水，令萬餘人囊沙壅水上流，引軍半渡，佯不勝，走還，龍且追信。信令人決壅水大至，且軍大半不得渡，信急擊殺龍且&quot;。○淓，宋元本作涉，亡作兇，均依汲古。</p><h3 id="大壯之隨" tabindex="-1">大壯之隨 <a class="header-anchor" href="#大壯之隨" aria-label="Permalink to “大壯之隨”">​</a></h3><h3 id="林辭-16" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-16" aria-label="Permalink to “林辭”">​</a></h3><p>有莘季女，為王妃後。貴夫壽子，母字四海。</p><h3 id="注-16" tabindex="-1">注 <a class="header-anchor" href="#注-16" aria-label="Permalink to “注”">​</a></h3><p>莘，草也。震象，兌為季女，大禹母有莘氏也。震為王，兌為妃，故曰為王妃後。震夫艮貴，故曰貴夫，艮壽震子，故曰壽子。兌澤故曰海。震卦數四，故曰四海，巽為母。○字，汲古作尊，依宋元本。</p><h3 id="大壯之蠱" tabindex="-1">大壯之蠱 <a class="header-anchor" href="#大壯之蠱" aria-label="Permalink to “大壯之蠱”">​</a></h3><h3 id="林辭-17" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-17" aria-label="Permalink to “林辭”">​</a></h3><p>德被八表，蠻夷率服。蝥賊不作，道無苛慝。</p><h3 id="注-17" tabindex="-1">注 <a class="header-anchor" href="#注-17" aria-label="Permalink to “注”">​</a></h3><p>震為德，艮為表，數八，故曰德被八表。互大坎為蠻夷，巽順，故曰率服。巽為蝥賊、為苛慝，艮為道，艮在上，故無苛慝。</p><h3 id="大壯之臨" tabindex="-1">大壯之臨 <a class="header-anchor" href="#大壯之臨" aria-label="Permalink to “大壯之臨”">​</a></h3><h3 id="林辭-18" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-18" aria-label="Permalink to “林辭”">​</a></h3><p>載日精光，驂駕六龍。祿命徹天，封為燕王。</p><h3 id="注-18" tabindex="-1">注 <a class="header-anchor" href="#注-18" aria-label="Permalink to “注”">​</a></h3><p>伏乾為日、為精光，坤為載，乾為龍，數六，乾行故曰驂駕六龍。乾為天、為祿，伏巽為命，故曰祿命徹天。震為王，兌為燕，故曰燕王。巽為誥命，故曰封。</p><h3 id="大壯之觀" tabindex="-1">大壯之觀 <a class="header-anchor" href="#大壯之觀" aria-label="Permalink to “大壯之觀”">​</a></h3><h3 id="林辭-19" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-19" aria-label="Permalink to “林辭”">​</a></h3><p>纓急縮頸，行不得前。五石示象，襄霸不成。</p><h3 id="注-19" tabindex="-1">注 <a class="header-anchor" href="#注-19" aria-label="Permalink to “注”">​</a></h3><p>巽為繩、為纓，巽躁故急，巽退故縮。艮為頸，言纓急項不得伸也。震為行，震覆故行不前，乾為前也。艮為石，巽卦數五，故曰五石。艮為象，故曰五石示象。伏乾為君，故曰襄。震為霸，震覆故曰襄霸不成。《左傳僖十四年》：&quot;隕石於宋五。&quot;後宋襄圖霸不成而死，以隕石為不祥。石，星石也。○不，元本作弗，非，依宋本、汲古。</p><h3 id="大壯之噬嗑" tabindex="-1">大壯之噬嗑 <a class="header-anchor" href="#大壯之噬嗑" aria-label="Permalink to “大壯之噬嗑”">​</a></h3><h3 id="林辭-20" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-20" aria-label="Permalink to “林辭”">​</a></h3><p>蛇失其公，戴麻當喪。哀悲哭泣，送死離鄉。</p><h3 id="注-20" tabindex="-1">注 <a class="header-anchor" href="#注-20" aria-label="Permalink to “注”">​</a></h3><p>通《井》。巽為蛇，震為公，坎失，故曰蛇失其公。巽為麻，艮為戴，兌折為喪，故曰戴麻當喪。卦正反兌口，故曰哀悲哭泣。坎為死，艮為鄉。○蛇失其公，汲古作蛇鄉其穴，非，依宋元本。</p><h3 id="大壯之賁" tabindex="-1">大壯之賁 <a class="header-anchor" href="#大壯之賁" aria-label="Permalink to “大壯之賁”">​</a></h3><h3 id="林辭-21" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-21" aria-label="Permalink to “林辭”">​</a></h3><p>回隤不安，兵革為患。掠我妻子，客屢饑寒。</p><h3 id="注-21" tabindex="-1">注 <a class="header-anchor" href="#注-21" aria-label="Permalink to “注”">​</a></h3><p>中爻震為馬，回隤病也。《詩》：&quot;我馬虺隤&quot;是也。艮為兵革，坎為患，艮手為掠，離妻震子，故曰掠我妻子。震客離飢，坎寒虺隤，《說文》又作隤，蓋傳寫異文不得，以與詩異，即定回為訛字。○回隤，汲古作四隤，依宋元本。屢，宋元本作屬，依汲古。</p><h3 id="大壯之剝" tabindex="-1">大壯之剝 <a class="header-anchor" href="#大壯之剝" aria-label="Permalink to “大壯之剝”">​</a></h3><h3 id="林辭-22" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-22" aria-label="Permalink to “林辭”">​</a></h3><p>乘風駕雨，與飛鳥俱。一舉千里，見吾愛母。</p><h3 id="注-22" tabindex="-1">注 <a class="header-anchor" href="#注-22" aria-label="Permalink to “注”">​</a></h3><p>坤為風，伏兌為雨，艮為鳥、為飛，乾卦數一，艮為舉，坤為裡，故曰一舉千里。坤為吾、為母，伏兌為見。○駕雨，宋本作雨橋，元本、汲古作禹，依《明夷》之《鼎》校。</p><h3 id="大壯之復" tabindex="-1">大壯之復 <a class="header-anchor" href="#大壯之復" aria-label="Permalink to “大壯之復”">​</a></h3><h3 id="林辭-23" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-23" aria-label="Permalink to “林辭”">​</a></h3><p>雷霆所擊，誅者五逆。劘滅無跡，有懼方息。</p><h3 id="注-23" tabindex="-1">注 <a class="header-anchor" href="#注-23" aria-label="Permalink to “注”">​</a></h3><p>震為雷霆，艮手為擊，坤殺故曰誅。乾順行，坤逆行，五陰故曰五逆。坤死故劘滅。坤虛故無跡。乾為惕、為懼。息者，生也，言乾陽從此漸息也。</p><h3 id="大壯之無妄" tabindex="-1">大壯之無妄 <a class="header-anchor" href="#大壯之無妄" aria-label="Permalink to “大壯之無妄”">​</a></h3><h3 id="林辭-24" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-24" aria-label="Permalink to “林辭”">​</a></h3><p>張氏揖酒，請謁左右。平叔枯槁，獨不蒙所。</p><h3 id="注-24" tabindex="-1">注 <a class="header-anchor" href="#注-24" aria-label="Permalink to “注”">​</a></h3><p>震為張，艮手為揖，伏兌為酒，故曰張氏揖酒。艮為求、為請謁，震左兌右，故請謁左右。伏坤為平，艮為叔，離為枯槁，離虛，故獨不蒙所。關西方言致力於一事為所。《書無逸》：&quot;君子所其無逸&quot;、《召誥》&quot;王敬作所&quot;是也，言獨不致意於平叔也。按：《史記陳丞相世家》：&quot;富人張負獨偉視平，歸謂其子仲曰：人固有美好如陳平而長貧賤者乎。乃以其孫女嫁之，並假以幣為內婦酒食之資&quot;，林用其事三四句，言平叔不能久枯槁也。○平叔，依宋元本，汲古作王時。</p><h3 id="大壯之大畜" tabindex="-1">大壯之大畜 <a class="header-anchor" href="#大壯之大畜" aria-label="Permalink to “大壯之大畜”">​</a></h3><h3 id="林辭-25" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-25" aria-label="Permalink to “林辭”">​</a></h3><p>坐爭立訟，紛紛匈匈。卒成禍亂，災及家公。</p><h3 id="注-25" tabindex="-1">注 <a class="header-anchor" href="#注-25" aria-label="Permalink to “注”">​</a></h3><p>艮為坐，震為立，三至上正反兩震言相對，故有爭訟之象而紛紛匈匈也。離為禍亂、為災，艮為家，乾父為公。</p><h3 id="大壯之頤" tabindex="-1">大壯之頤 <a class="header-anchor" href="#大壯之頤" aria-label="Permalink to “大壯之頤”">​</a></h3><h3 id="林辭-26" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-26" aria-label="Permalink to “林辭”">​</a></h3><p>霜降閉戶，蟄蟲隱處。不見日月，與死為伍。</p><h3 id="注-26" tabindex="-1">注 <a class="header-anchor" href="#注-26" aria-label="Permalink to “注”">​</a></h3><p>坤為門戶、為閉、為霜，故曰霜降閉戶。通《大過》。巽伏為蟄、為隱處、為蟲，艮為日，兌為月，巽伏故不見，坤為死也。</p><h3 id="大壯之大過" tabindex="-1">大壯之大過 <a class="header-anchor" href="#大壯之大過" aria-label="Permalink to “大壯之大過”">​</a></h3><h3 id="林辭-27" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-27" aria-label="Permalink to “林辭”">​</a></h3><p>鼠聚生怪，為我患悔。道絕不通，商旅失意。</p><h3 id="注-27" tabindex="-1">注 <a class="header-anchor" href="#注-27" aria-label="Permalink to “注”">​</a></h3><p>通《頤》。艮為鼠，震為生，坤為聚、為鬼怪、為患悔，坤為我，艮震皆為道路，坤閉故不通。震為商旅，坤喪故失意。《漢書五行志》：&quot;昭帝元鳳元年，燕有黃鼠銜其尾舞王宮端門中。未幾。燕王誅死&quot;。</p><h3 id="大壯之坎" tabindex="-1">大壯之坎 <a class="header-anchor" href="#大壯之坎" aria-label="Permalink to “大壯之坎”">​</a></h3><h3 id="林辭-28" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-28" aria-label="Permalink to “林辭”">​</a></h3><p>寒暑不當，軌度失常。一前一後，年歲鮮有。</p><h3 id="注-28" tabindex="-1">注 <a class="header-anchor" href="#注-28" aria-label="Permalink to “注”">​</a></h3><p>坎為寒，伏離為暑，震為道，故曰軌度。艮為常，坎失故曰失常。艮為前，震為後、為年歲，離虛坎病，故年歲鮮有。</p><h3 id="大壯之離" tabindex="-1">大壯之離 <a class="header-anchor" href="#大壯之離" aria-label="Permalink to “大壯之離”">​</a></h3><h3 id="林辭-29" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-29" aria-label="Permalink to “林辭”">​</a></h3><p>築室水上，危於一齒。醜寅不徙，辰巳有咎。</p><h3 id="注-29" tabindex="-1">注 <a class="header-anchor" href="#注-29" aria-label="Permalink to “注”">​</a></h3><p>通《坎》。中爻艮為室、為築，下坎，故曰築室水上。坎為危險。後天坎數一，故曰危於一齒。齒字恐訛，未詳其義。先天震居醜寅，後天艮居醜寅，故曰不徙。坎中爻也，先天兌居辰巳，後天巽居辰巳。離中爻也，澤風成大過，大過死故曰有咎。</p><h3 id="大壯之鹹" tabindex="-1">大壯之鹹 <a class="header-anchor" href="#大壯之鹹" aria-label="Permalink to “大壯之鹹”">​</a></h3><h3 id="林辭-30" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-30" aria-label="Permalink to “林辭”">​</a></h3><p>畜雞養狗，長息有儲。耕田得黍，主母喜舞。</p><h3 id="注-30" tabindex="-1">注 <a class="header-anchor" href="#注-30" aria-label="Permalink to “注”">​</a></h3><p>巽為雞，艮為狗，旁通《損》。震為長、為息，艮止故有儲。坤為田，震為耕、為黍，故耕田得黍。震為主、為喜、為舞，坤為母，故曰主母喜舞。○主，宋元本作王，依汲古。</p><h3 id="大壯之恆" tabindex="-1">大壯之恆 <a class="header-anchor" href="#大壯之恆" aria-label="Permalink to “大壯之恆”">​</a></h3><h3 id="林辭-31" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-31" aria-label="Permalink to “林辭”">​</a></h3><p>東壁餘光，數暗不明。主母嫉妬，亂我業事。</p><h3 id="注-31" tabindex="-1">注 <a class="header-anchor" href="#注-31" aria-label="Permalink to “注”">​</a></h3><p>震為東，伏艮為壁、為明，故曰餘光。兌昧故暗而不明。震為主，伏坤為母、為嫉妬，坤為事業、為我、為亂。○業事，汲古作事業，依宋元本，事詳《謙》之《屯》。</p><h3 id="大壯之遯" tabindex="-1">大壯之遯 <a class="header-anchor" href="#大壯之遯" aria-label="Permalink to “大壯之遯”">​</a></h3><h3 id="林辭-32" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-32" aria-label="Permalink to “林辭”">​</a></h3><p>剛柔相傷，火爛銷金。雕鷹制兔，伐楚有功。</p><h3 id="注-32" tabindex="-1">注 <a class="header-anchor" href="#注-32" aria-label="Permalink to “注”">​</a></h3><p>通《臨》。遯陰消陽，臨陽消陰，故曰剛柔相傷。乾金，艮為火，陰在下消陽，故曰火爛銷金。艮為黔喙、為雕鷹，震為兔、為楚、為伐，震樂，故伐楚有功。</p><h3 id="大壯之大壯" tabindex="-1">大壯之大壯 <a class="header-anchor" href="#大壯之大壯" aria-label="Permalink to “大壯之大壯”">​</a></h3><h3 id="林辭-33" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-33" aria-label="Permalink to “林辭”">​</a></h3><p>左有噬熊，右有嚙虎。前觸鐵矛，後躓強弩，無可抵者。</p><h3 id="注-33" tabindex="-1">注 <a class="header-anchor" href="#注-33" aria-label="Permalink to “注”">​</a></h3><p>震為左，兌為右，伏艮為熊虎，兌口，故曰左有噬熊，右有嚙虎。乾為前、為鐵，震為後，兌折故後躓。伏艮為刀兵，故曰矛、曰弩。抵，御也。艮為御，艮伏故無可御者。</p><h3 id="大壯之晉" tabindex="-1">大壯之晉 <a class="header-anchor" href="#大壯之晉" aria-label="Permalink to “大壯之晉”">​</a></h3><h3 id="林辭-34" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-34" aria-label="Permalink to “林辭”">​</a></h3><p>鄭國讒多，數被楚憂。征夫愁苦，民困無聊。</p><h3 id="注-34" tabindex="-1">注 <a class="header-anchor" href="#注-34" aria-label="Permalink to “注”">​</a></h3><p>坤為國、為平，故曰鄭國。鄭，町也，地多平町町然也。離上下兩兌口相背，故曰讒多。大壯震木為楚，坎為憂，震為征夫，坎為愁苦，坤為民，坎困故無聊。○征夫，宋元本作商人，依汲古。</p><h3 id="大壯之明夷" tabindex="-1">大壯之明夷 <a class="header-anchor" href="#大壯之明夷" aria-label="Permalink to “大壯之明夷”">​</a></h3><h3 id="林辭-35" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-35" aria-label="Permalink to “林辭”">​</a></h3><p>弓矢斯張，把彈弦折。丸發不至，道遇患害。</p><h3 id="注-35" tabindex="-1">注 <a class="header-anchor" href="#注-35" aria-label="Permalink to “注”">​</a></h3><p>坎為弓、為矢，震為張，坎為彈、為弦、為折，故曰把彈弦折。坎為丸，坎陷故不至。震為道，坎為患害。○斯，宋元本作其，依汲古。</p><h3 id="大壯之家人" tabindex="-1">大壯之家人 <a class="header-anchor" href="#大壯之家人" aria-label="Permalink to “大壯之家人”">​</a></h3><h3 id="林辭-36" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-36" aria-label="Permalink to “林辭”">​</a></h3><p>舉觴飲酒，未得至口。側弁醉酗，拔劍斫怒，武侯作悔。</p><h3 id="注-36" tabindex="-1">注 <a class="header-anchor" href="#注-36" aria-label="Permalink to “注”">​</a></h3><p>通《解》。坎為酒、為飲，震為觴、為舉、為口，震伏故未得至口。艮為弁，艮覆故曰側弁。離為惡人，故醉酗。坎為七、為劍，震為拔、為怒、為斫，故曰拔劍斫怒。震為武，坎為悔，故曰武侯作悔。按：《小雅》：&quot;賓之初筵，賓既醉止，載號載呶&quot;，又曰&quot;側弁之俄，屢舞傞傞&quot;，乃衛武公飲酒悔過之詩，故曰武公作悔。○弁，汲古作棄，依宋元本。斫，宋元本作相，依汲古。</p><h3 id="大壯之睽" tabindex="-1">大壯之睽 <a class="header-anchor" href="#大壯之睽" aria-label="Permalink to “大壯之睽”">​</a></h3><h3 id="林辭-37" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-37" aria-label="Permalink to “林辭”">​</a></h3><p>蒼鷹群行，相得旅前。王孫申公，驚奪我雄。北天門開，神火飛災。如不敬信，事入塵埃。</p><h3 id="注-37" tabindex="-1">注 <a class="header-anchor" href="#注-37" aria-label="Permalink to “注”">​</a></h3><p>此用遇卦象。伏艮為鷹，震色青，故曰蒼。伏坤為群，震為行、為旅，旅者，侶也，言結為伴旅而前行也。震為王公，艮為孫、為明，故為申，故曰王孫申公。震為驚，艮手為奪，震為武、為雄，伏坤為北，艮為天門，震為開，故曰北天門開。震為神，艮為火、為災、為飛，故曰神火飛災。乾為信，坤為疑，艮為塵埃。○宋元本缺此林。</p><h3 id="大壯之蹇" tabindex="-1">大壯之蹇 <a class="header-anchor" href="#大壯之蹇" aria-label="Permalink to “大壯之蹇”">​</a></h3><h3 id="林辭-38" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-38" aria-label="Permalink to “林辭”">​</a></h3><p>穿屋相宜，利倍我北。循邪詭道，逃不可得。南北望邑，遂歸入室。</p><h3 id="注-38" tabindex="-1">注 <a class="header-anchor" href="#注-38" aria-label="Permalink to “注”">​</a></h3><p>艮屋，坎為穿，故曰穿屋。坎為北，巽利坤我，故曰利倍我北。坎為邪，艮為道，震往為逃，震覆故不得逃離。南坎北離，目為望，艮為邑，故曰南北望邑。坎為室，故曰入室。○屋，宋元本作空，依汲古。逃，汲古作迎，依宋元本。</p><h3 id="大壯之解" tabindex="-1">大壯之解 <a class="header-anchor" href="#大壯之解" aria-label="Permalink to “大壯之解”">​</a></h3><h3 id="林辭-39" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-39" aria-label="Permalink to “林辭”">​</a></h3><p>壽如松喬，與日月俱。常安康樂，不罹禍憂。</p><h3 id="注-39" tabindex="-1">注 <a class="header-anchor" href="#注-39" aria-label="Permalink to “注”">​</a></h3><p>此用《大壯》象。伏艮為壽、為松喬，赤鬆子，王喬，皆古仙人名。艮日兌月，艮為常、為安，震為康樂，在外故不憂。</p><h3 id="大壯之損" tabindex="-1">大壯之損 <a class="header-anchor" href="#大壯之損" aria-label="Permalink to “大壯之損”">​</a></h3><h3 id="林辭-40" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-40" aria-label="Permalink to “林辭”">​</a></h3><p>出門望東，伯仲不來。疾病為患，使母憂嘆。</p><h3 id="注-40" tabindex="-1">注 <a class="header-anchor" href="#注-40" aria-label="Permalink to “注”">​</a></h3><p>艮門、震出、震東，艮為觀，故曰望東。震為伯，艮止故不來。坤為疾病、為患、為憂、為母，震為嘆也。</p><h3 id="大壯之益" tabindex="-1">大壯之益 <a class="header-anchor" href="#大壯之益" aria-label="Permalink to “大壯之益”">​</a></h3><h3 id="林辭-41" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-41" aria-label="Permalink to “林辭”">​</a></h3><p>太姒之孫，周文九子。鹹遂受成，寵貴富有。</p><h3 id="注-41" tabindex="-1">注 <a class="header-anchor" href="#注-41" aria-label="Permalink to “注”">​</a></h3><p>坤為母后，故曰太姒。艮為孫，太姒者，文王之妃。詩&quot;太姒嗣徽音&quot;是也。《春秋傳》曰武王同母弟八人，是並武王為九子也。震為周，坤為文，震為子，數九，故曰九子。艮為成，坤為受，艮為寵貴，坤為富有，言太姒教誨諸子，成武王周公之德而富貴。○姒，汲古作姬，依宋元本。</p><h3 id="大壯之夬" tabindex="-1">大壯之夬 <a class="header-anchor" href="#大壯之夬" aria-label="Permalink to “大壯之夬”">​</a></h3><h3 id="林辭-42" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-42" aria-label="Permalink to “林辭”">​</a></h3><p>桃李華實，纍纍日息。長大成熟，甘美可食，為我利福。</p><h3 id="注-42" tabindex="-1">注 <a class="header-anchor" href="#注-42" aria-label="Permalink to “注”">​</a></h3><p>兌為反巽，巽木故曰桃李。兌為華，《大過九五》&quot;枯楊生華&quot;是也。乾為木果，故曰實，重乾故纍纍日息。乾為日、為長大、為美好，兌為食，乾為福，伏坤為成熟、為我、為利。○纍纍，宋元木作纍纍，依汲古。</p><h3 id="大壯之姤" tabindex="-1">大壯之姤 <a class="header-anchor" href="#大壯之姤" aria-label="Permalink to “大壯之姤”">​</a></h3><h3 id="林辭-43" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-43" aria-label="Permalink to “林辭”">​</a></h3><p>昬禮不明，男女失常。行露反言，出爭我訟。</p><h3 id="注-43" tabindex="-1">注 <a class="header-anchor" href="#注-43" aria-label="Permalink to “注”">​</a></h3><p>通《復》。坤為昬、為禮，故曰昬禮不明。乾男坤女，姤坤消乾，復乾消坤，故男女失常。震為行，坤為水、為露，《詩》&quot;厭浥行露&quot;是也。震為言、為反，故曰反言，又言又乾為言，巽為覆兌，兌言與上乾言相背，故曰爭訟。《行露》詩 &quot;何以速我訟&quot;，用其事也。○昏，依元本，宋、汲古作婚。露反，依宋元本，汲古作路有，非。</p><h3 id="大壯之萃" tabindex="-1">大壯之萃 <a class="header-anchor" href="#大壯之萃" aria-label="Permalink to “大壯之萃”">​</a></h3><h3 id="林辭-44" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-44" aria-label="Permalink to “林辭”">​</a></h3><p>室穿敝漏，破桴殘缺。陰弗能完，瓦碎不全。</p><h3 id="注-44" tabindex="-1">注 <a class="header-anchor" href="#注-44" aria-label="Permalink to “注”">​</a></h3><p>艮為室，兌毀故穿，巽為敝漏，故曰室穿敝漏。伏震為桴，兌毀折故曰破桴、曰殘缺。坤為陰，兌折故弗完，故瓦碎不全。艮為瓦也。</p><h3 id="大壯之升" tabindex="-1">大壯之升 <a class="header-anchor" href="#大壯之升" aria-label="Permalink to “大壯之升”">​</a></h3><h3 id="林辭-45" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-45" aria-label="Permalink to “林辭”">​</a></h3><p>數窮廓落，困於厯室。往登玉堂，與堯侑食。</p><h3 id="注-45" tabindex="-1">注 <a class="header-anchor" href="#注-45" aria-label="Permalink to “注”">​</a></h3><p>中爻兌數十，坤納癸，亦數十，故曰數窮，坤虛故廓落。伏艮為室、為時，故曰厯室，震為往、為登、為王，伏艮為堂，故往登玉堂。震為帝，故曰堯。兌為食，震為侑，故曰與堯侑食。○堯，汲古作老，依宋元本。</p><h3 id="大壯之困" tabindex="-1">大壯之困 <a class="header-anchor" href="#大壯之困" aria-label="Permalink to “大壯之困”">​</a></h3><h3 id="林辭-46" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-46" aria-label="Permalink to “林辭”">​</a></h3><p>道濕為坑，輪陷躓僵。南國作諱，使我多畏。</p><h3 id="注-46" tabindex="-1">注 <a class="header-anchor" href="#注-46" aria-label="Permalink to “注”">​</a></h3><p>伏震為道，下坎，故道濕，故為坑。坎為輪、為陷、為躓、為僵，離為南，伏艮為國，坎為諱，諱，避也，言南國禁忌多也。坎為畏，困正互兩坎，故多畏。○輪，依汲古，宋元本作輸。</p><h3 id="大壯之井" tabindex="-1">大壯之井 <a class="header-anchor" href="#大壯之井" aria-label="Permalink to “大壯之井”">​</a></h3><h3 id="林辭-47" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-47" aria-label="Permalink to “林辭”">​</a></h3><p>鰥寡孤獨，福祿苦薄。入室無妻，武子悲哀。</p><h3 id="注-47" tabindex="-1">注 <a class="header-anchor" href="#注-47" aria-label="Permalink to “注”">​</a></h3><p>通《噬嗑》。艮為鰥，巽為寡，坎為孤獨，震為福祿，坎為薄，故曰福祿苦薄。坎為室，巽入，離為坎妻，坎失，故入室無妻。震為武人，井正覆皆兌口，故曰悲哀。《左傳襄二十五年》：&quot;崔杼取棠薑，筮得入其宮不見其妻兇&quot;，困三繇詞，林用其事。○武，汲古訛我，依宋元本。</p><h3 id="大壯之革" tabindex="-1">大壯之革 <a class="header-anchor" href="#大壯之革" aria-label="Permalink to “大壯之革”">​</a></h3><h3 id="林辭-48" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-48" aria-label="Permalink to “林辭”">​</a></h3><p>舉袂覆目，不見日月。衣衾杖機，就其夜室。</p><h3 id="注-48" tabindex="-1">注 <a class="header-anchor" href="#注-48" aria-label="Permalink to “注”">​</a></h3><p>通《蒙》。震為袂、為舉，艮為目，《士喪禮》&quot;幎目用緇，尺二寸&quot;註：覆目者也，坎隱故覆目，故不見日月。艮日坎月也。坤為衣衾，震木為杖，艮為幾，故曰衣衾幾杖。坎為夜室，古以坎有棺橔象，就夜室者言死也。首句似用吳王夫差幎目而死事。○袂，宋元本作被，依汲古。</p><h3 id="大壯之鼎" tabindex="-1">大壯之鼎 <a class="header-anchor" href="#大壯之鼎" aria-label="Permalink to “大壯之鼎”">​</a></h3><h3 id="林辭-49" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-49" aria-label="Permalink to “林辭”">​</a></h3><p>長尾踒跎，畫地為河。深不可涉，絕無以北，憫然憤息。</p><h3 id="注-49" tabindex="-1">注 <a class="header-anchor" href="#注-49" aria-label="Permalink to “注”">​</a></h3><p>通《屯》。艮為尾，巽為長，下互坤形長，故曰長尾，踒跎當為委佗。《詩》&quot;委委佗佗&quot;是也，所以形容長尾。坤為地、為河，艮手為畫，上坎水下坤水，故深不可涉。坎為北，兌折，故絕無以北。坎為憫、為憤、為太息。</p><h3 id="大壯之震" tabindex="-1">大壯之震 <a class="header-anchor" href="#大壯之震" aria-label="Permalink to “大壯之震”">​</a></h3><h3 id="林辭-50" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-50" aria-label="Permalink to “林辭”">​</a></h3><p>晨風文翰，大舉就溫。昧過我邑，羿無所得。</p><h3 id="注-50" tabindex="-1">注 <a class="header-anchor" href="#注-50" aria-label="Permalink to “注”">​</a></h3><p>震旦為晨，伏巽為風，伏離為文，震為羽翰，故曰晨風文翰。《詩》&quot;鬱彼晨風&quot;《傳》：晨風，鸇也。《周書王會篇》：&quot;蜀人以文翰，文翰若皋雞&quot;。艮為鳥，亦艮象也。震舉離溫，艮為邑、為我，坎為昧，故曰昧過我邑，言夜過也。離為惡人，故曰羿。離虛故無所得。羿，后羿，善射，纂［當作簒］夏，後氏者也。</p><h3 id="大壯之艮" tabindex="-1">大壯之艮 <a class="header-anchor" href="#大壯之艮" aria-label="Permalink to “大壯之艮”">​</a></h3><h3 id="林辭-51" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-51" aria-label="Permalink to “林辭”">​</a></h3><p>出入節時，南北無憂。行者亟至，在外來歸。</p><h3 id="注-51" tabindex="-1">注 <a class="header-anchor" href="#注-51" aria-label="Permalink to “注”">​</a></h3><p>中爻震出坎入，艮為時、為節，震為南，坎為北、為憂，震樂故無憂。震為行、為亟，震反，故來歸。○來歸，宋元本作歸來，依汲古。</p><h3 id="大壯之漸" tabindex="-1">大壯之漸 <a class="header-anchor" href="#大壯之漸" aria-label="Permalink to “大壯之漸”">​</a></h3><h3 id="林辭-52" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-52" aria-label="Permalink to “林辭”">​</a></h3><p>陽氏狂惑，季孫亂憒。陪臣執政，平子拘折，我心不快。</p><h3 id="注-52" tabindex="-1">注 <a class="header-anchor" href="#注-52" aria-label="Permalink to “注”">​</a></h3><p>互離為陽，伏震為狂，謂陽虎也。坎為惑，艮為季、為孫，離亂坎憒，故曰季氏亂憒，謂平子也。艮為臣僕，艮手為執，巽為政令，故曰陪臣執政。坎為平，震為子，坎為拘折，言平子被囚也。坎為心、為憂，艮為我，故曰我心不快。按：《左傳》&quot;陽虎為季氏陪臣，專政作亂，囚季平子，欲殺之，遇救免&quot;。</p><h3 id="大壯之歸妹" tabindex="-1">大壯之歸妹 <a class="header-anchor" href="#大壯之歸妹" aria-label="Permalink to “大壯之歸妹”">​</a></h3><h3 id="林辭-53" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-53" aria-label="Permalink to “林辭”">​</a></h3><p>五烏六鴟，相對蹲跂。禮讓不興，虞芮爭訟。</p><h3 id="注-53" tabindex="-1">注 <a class="header-anchor" href="#注-53" aria-label="Permalink to “注”">​</a></h3><p>伏艮為烏、為鴟，坎數五，又卦數六，故曰五烏六鴟。震為立，故曰蹲跂。震決躁，兌附決，故禮讓不興。坎為憂虞，震為草莽，故曰虞芮。卦上震下兌，而震言與兌言相背，故曰爭訟。昔虞芮二國爭田不決，欲訟於西伯，及入周界耕，皆讓畔，乃慚而還。首句義未詳，八烏，星名。</p><h3 id="大壯之豐" tabindex="-1">大壯之豐 <a class="header-anchor" href="#大壯之豐" aria-label="Permalink to “大壯之豐”">​</a></h3><h3 id="林辭-54" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-54" aria-label="Permalink to “林辭”">​</a></h3><p>顧念所生，隔在東平。遭離滿沸，河川決潰。幸得無恙，復歸相室。</p><h3 id="注-54" tabindex="-1">注 <a class="header-anchor" href="#注-54" aria-label="Permalink to “注”">​</a></h3><p>離目為顧，伏坎為念，震為生，坎為隔，震東坎平，故曰東平。互大坎為滿沸、為河川、為潰決、為病恙，震出故得無恙。坎為室，震為歸。○顧，汲古作願，依宋元本，此有故事，未能確指。末句汲古作復生歸室，依宋元本。</p><h3 id="大壯之旅" tabindex="-1">大壯之旅 <a class="header-anchor" href="#大壯之旅" aria-label="Permalink to “大壯之旅”">​</a></h3><h3 id="林辭-55" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-55" aria-label="Permalink to “林辭”">​</a></h3><p>追獵東走，兔逃我後。吾銳不利，獨空無有。</p><h3 id="注-55" tabindex="-1">注 <a class="header-anchor" href="#注-55" aria-label="Permalink to “注”">​</a></h3><p>通《節》。震為追獵、為東走、為兔、為後，坎為棘，故為銳。巽為利，坎蹇，故不利。離虛故空無有，坎為獨也。</p><h3 id="大壯之巽" tabindex="-1">大壯之巽 <a class="header-anchor" href="#大壯之巽" aria-label="Permalink to “大壯之巽”">​</a></h3><h3 id="林辭-56" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-56" aria-label="Permalink to “林辭”">​</a></h3><p>犬吠非主，上下膠擾。敵人襲戰，閔王逃走。</p><h3 id="注-56" tabindex="-1">注 <a class="header-anchor" href="#注-56" aria-label="Permalink to “注”">​</a></h3><p>伏艮為犬，震為鳴、為吠、為主，震伏，故曰非主。艮為上，震為下，坎為膏，為膠，離亂，故曰上下膠擾。震為人、為戰，三至上正反震艮相對，故曰敵人襲戰。坎為閔，震為王、為走，故曰閔王逃走。《戰國策》：&quot;樂毅伐齊，至濟西，閔王走莒&quot;是也。○膠，依宋元本，汲古作渾。</p><h3 id="大壯之兌" tabindex="-1">大壯之兌 <a class="header-anchor" href="#大壯之兌" aria-label="Permalink to “大壯之兌”">​</a></h3><h3 id="林辭-57" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-57" aria-label="Permalink to “林辭”">​</a></h3><p>嵩高岱宗，峻直且神。觸石膚寸，千里蒙恩。</p><h3 id="注-57" tabindex="-1">注 <a class="header-anchor" href="#注-57" aria-label="Permalink to “注”">​</a></h3><p>通《艮》。艮為山，互坎為中，故曰嵩高。互震為東，故曰岱宗。艮為高峻，震為神、為觸，艮為石、為膚，故曰觸石膚寸。震為千里，坎為恩澤，故曰千里蒙恩。《公羊傳》：&quot;觸石而出，膚寸而合，不崇朝而雨遍天下者，惟泰山之雲耳&quot;。註：側手為扶，覆手為寸。膚寸皆艮象。</p><h3 id="大壯之渙" tabindex="-1">大壯之渙 <a class="header-anchor" href="#大壯之渙" aria-label="Permalink to “大壯之渙”">​</a></h3><h3 id="林辭-58" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-58" aria-label="Permalink to “林辭”">​</a></h3><p>陳魚觀社，佷荒逾矩。為民開緒，亡其祖考。</p><h3 id="注-58" tabindex="-1">注 <a class="header-anchor" href="#注-58" aria-label="Permalink to “注”">​</a></h3><p>巽為魚，震為陳，艮為社、為觀，《春秋隱公五年》&quot;公如棠陳魚而觀之&quot;，又《莊二十三年》&quot;如齊，公觀社，非禮也&quot;，故曰佷荒逾矩，言荒淫逾越規矩也。坎為曲、為矩、為民，巽為緒，艮為壽，故曰祖考。坎失故亡其祖考。佷，音恆，有驕痴二義。《後漢蔡邕傳》&quot;董卓自佷用&quot;是也。○第二句汲古訛狼虎逾距，依宋元本。</p><h3 id="大壯之節" tabindex="-1">大壯之節 <a class="header-anchor" href="#大壯之節" aria-label="Permalink to “大壯之節”">​</a></h3><h3 id="林辭-59" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-59" aria-label="Permalink to “林辭”">​</a></h3><p>四壁無戶，三步一止。東西南北，利不可得。</p><h3 id="注-59" tabindex="-1">注 <a class="header-anchor" href="#注-59" aria-label="Permalink to “注”">​</a></h3><p>艮為壁，震卦數四，故曰四壁。坤為戶，坎塞坤故無戶。震為步，數三，故曰三步。艮止，坎數一，故曰一止。震東兌西，震南坎北，巽為利，巽覆，故利不可得。</p><h3 id="大壯之中孚" tabindex="-1">大壯之中孚 <a class="header-anchor" href="#大壯之中孚" aria-label="Permalink to “大壯之中孚”">​</a></h3><h3 id="林辭-60" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-60" aria-label="Permalink to “林辭”">​</a></h3><p>求君衣裳，情不可當。觸諱西行，為伯生殃。君之上歡，得其安存。</p><h3 id="注-60" tabindex="-1">注 <a class="header-anchor" href="#注-60" aria-label="Permalink to “注”">​</a></h3><p>震為君，艮為求，震為衣裳、為健，故不可當。震為觸、為行，巽伏故曰諱。諱，避也。兌為西，故曰觸諱西行。震為伯、為生，兌折故生殃。震為君、為歡，艮為安，《春秋》：&quot;蔡昭侯如楚，有善裘，子常欲之，弗與，留楚三年，後蔡人聞之，固請獻之，遂得歸&quot;。○上歡，汲古作上安，依宋元本。</p><h3 id="大壯之小過" tabindex="-1">大壯之小過 <a class="header-anchor" href="#大壯之小過" aria-label="Permalink to “大壯之小過”">​</a></h3><h3 id="林辭-61" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-61" aria-label="Permalink to “林辭”">​</a></h3><p>春鴻飛東，以馬貿金，利可得深。</p><h3 id="注-61" tabindex="-1">注 <a class="header-anchor" href="#注-61" aria-label="Permalink to “注”">​</a></h3><p>震為春、為鴻、為飛、為東、為馬，巽為商旅，故曰貿。艮為金，故曰貿金。坎為深也。巽為利，利可得深，言得利多也。</p><h3 id="大壯之既濟" tabindex="-1">大壯之既濟 <a class="header-anchor" href="#大壯之既濟" aria-label="Permalink to “大壯之既濟”">​</a></h3><h3 id="林辭-62" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-62" aria-label="Permalink to “林辭”">​</a></h3><p>禾生蟲蠹，遠自克賊，使我無得。此用遇卦象。</p><h3 id="注-62" tabindex="-1">注 <a class="header-anchor" href="#注-62" aria-label="Permalink to “注”">​</a></h3><p>震為禾、為生，巽為蟲、為賊，伏坤為我，坤虛故無得。</p><h3 id="大壯之未濟" tabindex="-1">大壯之未濟 <a class="header-anchor" href="#大壯之未濟" aria-label="Permalink to “大壯之未濟”">​</a></h3><h3 id="林辭-63" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-63" aria-label="Permalink to “林辭”">​</a></h3><p>桀亂無道，民散不聚。背室棄家，遁逃出走。</p><h3 id="注-63" tabindex="-1">注 <a class="header-anchor" href="#注-63" aria-label="Permalink to “注”">​</a></h3><p>離為惡人，故曰桀。離為亂，震為道，坎隱故無道。坤為民、為聚，三爻間隔，故民散不聚。坎為室，艮為背，故曰背室。艮為家，坎失，故曰棄家。坎伏為遁，震走為逃也。凡震艮皆用半象。</p>',322)])])}const m=e(l,[["render",n]]);export{p as __pageData,m as default};
